questions.solution:
function shallowEqual(a, b) {
  const aKeys = Object.keys(a);
  const bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;
  return aKeys.every((key) => Object.hasOwn(b, key) && Object.is(a[key], b[key]));
}

console.log(shallowEqual({ sku: "RICE-5", qty: 2 }, { qty: 2, sku: "RICE-5" }));
console.log(shallowEqual({ sku: "RICE-5" }, { sku: "RICE-5", qty: 2 }));
console.log(shallowEqual({ price: NaN }, { price: NaN }));
console.log(shallowEqual({ items: [1] }, { items: [1] }));

