function createLine(sku) {
  let qty = 1;
  return {
    sku,
    get qty() {
      return qty;
    },
    set qty(value) {
      if (!Number.isInteger(value) || value < 1 || value > 99) throw new RangeError(`bad qty ${value}`);
      qty = value;
    },
  };
}

const line = createLine("RICE-5");
line.qty = 3;
for (const bad of [0, 2.5, "4", 100]) {
  try {
    line.qty = bad;
  } catch (error) {
    console.log(`${error.name}: ${JSON.stringify(bad)}`);
  }
}
console.log(line.qty);

